#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<int> adj(N, 0);
    for (int i = 0; i < M; ++i) {
        int X, Y;
        cin >> X >> Y;
        --X;
        --Y;
        adj[X] |= 1 << Y;
        adj[Y] |= 1 << X;
    }

    int total = 1 << N;
    vector<unsigned char> independent(total, 0);
    independent[0] = 1;

    int answer = 0;
    for (int mask = 1; mask < total; ++mask) {
        int vertex = __builtin_ctz(static_cast<unsigned>(mask));
        int rest = mask & (mask - 1);
        independent[mask] = independent[rest] && !(adj[vertex] & rest);
        answer += independent[mask];
    }

    cout << answer << '\n';
    return 0;
}
